{
  "request_kind": "general",
  "focus": "Identificar os cuidados exigidos pela política antes de compartilhar dados com um fornecedor externo.",
  "known_conditions": [
    {
      "text": "O destinatário considerado é um fornecedor externo.",
      "quote": "com um fornecedor externo"
    },
    {
      "text": "Os cuidados solicitados são anteriores ao compartilhamento dos dados.",
      "quote": "antes de compartilhar dados"
    }
  ],
  "exclusions": [],
  "unknown_conditions": [
    "Qual é a política mencionada e quais exigências ela estabelece."
  ],
  "decision": "proceed",
  "clarification": null
}

{
  "items": [
    {
      "need": "Para dados públicos, verificar se estão aprovados para uso público e utilizar um canal empresarial aprovado.",
      "use": "category",
      "condition": "Quando os dados a compartilhar forem classificados como públicos.",
      "scope_link": {
        "question_quote": "antes de compartilhar dados com um fornecedor externo",
        "explanation": "A regra estabelece a condição de divulgação e o canal mínimo para compartilhar dados públicos externamente."
      },
      "supports": [
        {
          "unit_id": "DOC-005::unit-9b0d28fc0e3086af15def6c5a4d43fa93965cbbaa1b1a4ddf2803d4fb420ec35",
          "quote": "Public | May be shared when approved for public use. | Approved business channel."
        }
      ]
    },
    {
      "need": "Para dados internos, verificar a necessidade legítima de negócio e utilizar um canal gerenciado pela empresa.",
      "use": "category",
      "condition": "Quando os dados a compartilhar forem classificados como internos.",
      "scope_link": {
        "question_quote": "antes de compartilhar dados com um fornecedor externo",
        "explanation": "A regra condiciona o compartilhamento externo de dados internos à necessidade de negócio e ao canal corporativo gerenciado."
      },
      "supports": [
        {
          "unit_id": "DOC-005::unit-9b0d28fc0e3086af15def6c5a4d43fa93965cbbaa1b1a4ddf2803d4fb420ec35",
          "quote": "Internal | Share only for legitimate business need. | Corporate-managed channel."
        }
      ]
    },
    {
      "need": "Para dados confidenciais, confirmar destinatário autorizado e finalidade de negócio aprovada; utilizar transferência segura aprovada ou plataforma controlada adequada à classificação, com acesso limitado aos destinatários pretendidos. O uso de e-mail corporativo, por si só, não torna uma transferência aprovada ou segura.",
      "use": "category",
      "condition": "Quando os dados a compartilhar forem classificados como confidenciais.",
      "scope_link": {
        "question_quote": "antes de compartilhar dados com um fornecedor externo",
        "explanation": "As regras definem as condições de autorização, finalidade, acesso e canal para compartilhar informações confidenciais externamente."
      },
      "supports": [
        {
          "unit_id": "DOC-005::unit-9b0d28fc0e3086af15def6c5a4d43fa93965cbbaa1b1a4ddf2803d4fb420ec35",
          "quote": "Confidential | Share only with an authorized recipient and approved business purpose. | Approved secure transfer or controlled platform; access limited to intended recipients."
        },
        {
          "unit_id": "DOC-005::unit-2fee2bb245a7ce31586728f0d21e26342a23219879b805fcea42718d7b2c8a88",
          "quote": "Confidential information shared externally must use an approved secure channel or controlled platform appropriate to the information classification. Corporate email alone does not convert an otherwise unapproved transfer into an approved secure transfer."
        }
      ]
    },
    {
      "need": "Para dados restritos, obter autorização explícita conforme o controle de segurança ou jurídico aplicável, documentar essa autorização e utilizar mecanismo aprovado para dados restritos.",
      "use": "category",
      "condition": "Quando os dados a compartilhar forem classificados como restritos.",
      "scope_link": {
        "question_quote": "antes de compartilhar dados com um fornecedor externo",
        "explanation": "A regra exige autorização explícita documentada e mecanismo específico aprovado para compartilhamento externo de dados restritos."
      },
      "supports": [
        {
          "unit_id": "DOC-005::unit-9b0d28fc0e3086af15def6c5a4d43fa93965cbbaa1b1a4ddf2803d4fb420ec35",
          "quote": "Restricted | External sharing requires explicit authorization under the applicable security or legal control. | Approved restricted-data mechanism and documented authorization."
        }
      ]
    },
    {
      "need": "Se o fornecedor for uma transportadora, limitar os dados ao necessário para executar o serviço logístico contratado. Dados confidenciais de clientes ou remessas não podem ser enviados por e-mail comum desprotegido apenas porque a transportadora é contratada.",
      "use": "category",
      "condition": "Quando o fornecedor externo for uma transportadora; a vedação de e-mail comum desprotegido aplica-se a dados de clientes ou remessas classificados como confidenciais.",
      "scope_link": {
        "question_quote": "antes de compartilhar dados com um fornecedor externo",
        "explanation": "A regra disciplina esse mesmo compartilhamento para a categoria de fornecedores que executam transporte."
      },
      "supports": [
        {
          "unit_id": "DOC-005::unit-7c8625b003fc6835188e4cc28881508738aba9b952c95c306256f96faadc7b87",
          "quote": "Transportation carriers may receive only the information required to execute the contracted logistics service. Customer or shipment data classified as confidential must not be transmitted through ordinary unprotected email merely because the recipient is a contracted carrier."
        }
      ]
    },
    {
      "need": "Quando houver exceção, documentar a justificativa de negócio e obter as aprovações definidas pelos controles de segurança e de autoridade aplicáveis; um procedimento operacional não pode criar sozinho uma exceção à política corporativa.",
      "use": "category",
      "condition": "Quando houver exceção às regras de compartilhamento.",
      "scope_link": {
        "question_quote": "antes de compartilhar dados com um fornecedor externo",
        "explanation": "A regra determina os requisitos para uma exceção ao compartilhamento regulado pela política, sem impor aprovações de exceção a todos os casos."
      },
      "supports": [
        {
          "unit_id": "DOC-005::unit-3e2cd1d6aa0b17f415f5cfb78e0895519691a34eabb2fd7e1907e495aef661fa",
          "quote": "Exceptions require documented business justification and the approvals defined by the applicable security and authority controls. An operational SOP cannot independently create an exception to a corporate policy."
        }
      ]
    }
  ],
  "action": {
    "kind": "complete"
  }
}

